head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil50200n";
scwin.form = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_sessionFill();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil50200n.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? ""); } },
        { childId: "__rb1", fn: function () { return "전체 " + String((dma_pageContext.get("totalCountIntValue") ?? "")) + "건 [" + String((dma_pageContext.get("currentPage") ?? "")) + "/" + String((dma_pageContext.get("totalPageCount") ?? "")) + "Page]"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.form = (document.prelistPageForm || { elements: [] });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil50200n.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil50200n' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_viewDetail();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_idAssgn_oncellclick
 * @description grd_idAssgn 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_idAssgn_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_idAssgn');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_idAssgn */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["listTpClssCd"] === '00' || r["listTpClssCd"] === '') { await scwin.viewDetail(r["bzProcsNo"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_idAssgn.oncellclick' });
    }
};

/**
 * @method
 * @name btn_openAssgnPop_onclick
 * @description 「신규작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_openAssgnPop_onclick = async function(e){
    try {
        await scwin.openAssgnPop()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil50200n.btn_openAssgnPop_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_52_onclick
 * @description krxpage_pagenavigator_52 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_52_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_52.page' }); } await scwin.fncSearch(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_viewDetail
 * @description view Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/clmSchdlNoti.do?method=loadDetail&bzCd=1",
        ref: "dma_viewDetailReq",
        target: "dlt_idAssgn=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/listInvstg/idAssgnStat.do",
        ref: "dma_searchCorpListByBeginIndexReq",
        target: "dlt_idAssgn=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_idAssgn_fmt_comNm
 * @description grd id Assgn fmt com Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_idAssgn_fmt_comNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_idAssgn");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "listTpClssCd") ?? '') : '');
        if (['00',''].indexOf(v) >= 0) { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "comNm") : '') ?? '') + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_idAssgn.comNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name viewDetail
 * @description view Detail 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewDetail = async function (bzProcsNo) {
    $c.util.getComponent('dma_viewDetailReq').set('bzProcsNo', bzProcsNo);
    scwin.form.action = '/listInvstg/clmSchdlNoti.do?method=loadDetail&bzCd=1';
    $c.util.getComponent('dma_viewDetailReq').set('method', 'loadDetail');
    await scwin.tx_viewDetail();
};

/**
 * @method
 * @name openAssgnPop
 * @description open Assgn Pop 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openAssgnPop = async function () {
    let url = '/jldfil50210/jldfil50210.xml';
    const tp = "konex";
    if (tp !== '') {
        w = '500';
        h = '300';
        l = screen.width / 2 - w / 2;
        t = screen.height / 2 - h / 2;
        if (tp === 'konex') {
            url = '/jldfil50210/jldfil50210.xml?method=choiceAssgnTp&assgnTp=' + 'konex';
        }
        await $c.win.openPopup(url, { id: "assgnPop", scrollbars: false, resizable: false, width: "500", height: "320", type: "pageFramePopup" }, { method: "choiceAssgnTp", assgnTp: "konex" });
    } else {
        await $c.win.alert('법인 배정 구분을 선택 하십시오.');
    }
};

/**
 * @method
 * @name fncSearch
 * @description fnc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncSearch = async function () {
    const pageIndex = $c.util.getComponent('dma_viewDetailReq').get('pageIndex');
    $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pageIndex);
    await scwin.searchCorpListByBeginIndex();
};

/**
 * @method
 * @name searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpListByBeginIndex = async function () {
    (document.prelistPageForm || { elements: [] }).action = "/listInvstg/idAssgnStat.do";
    const nr = await scwin.tx_searchCorpListByBeginIndex();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil50200/jldfil50200.xml");
    }
};
